examples.template:
MonarchDecisionCard(
    options = options,
    value = value,
    title = {{title}},
    reason = reason,
    decidedAt = {{decidedAt|millis}},
    now = {{now|millis}},
    decidedBy = {{decidedBy}},
    onDecide = { decision ->
        // A real app stores the decision, with saving set while it does.
        value = decision.value
        reason = decision.reason
    },
) {
    FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2), verticalArrangement = Arrangement.Center) {
        MonarchText(text = {{context.label}})
        MonarchBadge(text = {{context.badge}}, tone = MonarchTone.Info)
        MonarchText(text = {{context.text}})
    }
}

examples.setupTemplate:
var value by remember { mutableStateOf<String?>({{value}}) }
var reason by remember { mutableStateOf<String?>({{reason}}) }
val options = listOf(
    MonarchDecisionOption(label = {{options.0.label}}, value = {{options.0.value}}, tone = {{options.0.tone|tone}}),
    MonarchDecisionOption(label = {{options.1.label}}, value = {{options.1.value}}, tone = {{options.1.tone|tone}}),
    MonarchDecisionOption(
        label = {{options.2.label}},
        value = {{options.2.value}},
        note = {{options.2.note}},
        tone = {{options.2.tone|tone}},
        reasonRequired = {{options.2.reasonRequired}},
    ),
)

examples.setup:
var value by remember { mutableStateOf<String?>("review") }
var reason by remember { mutableStateOf<String?>("Check with the team first") }
val options = listOf(
    MonarchDecisionOption(label = "Keep", value = "keep", tone = MonarchTone.Success),
    MonarchDecisionOption(label = "Review", value = "review", tone = MonarchTone.Warning),
    MonarchDecisionOption(
        label = "Let lapse",
        value = "lapse",
        note = "Reminders stop and one final notice is sent before it expires.",
        tone = MonarchTone.Danger,
        reasonRequired = true,
    ),
)

